(function(){(window.upwHoverFx=window.upwHoverFx||{}).depth_layers={pointer:!0,reduceSkip:!0,run:function(n){var r=Array.prototype.slice.call(n.children).filter(function(t){return t.nodeType===1&&getComputedStyle(t).position!=="absolute"});if(r.length){var o=parseFloat(n.getAttribute("data-hover-depth"))||1;n.addEventListener("pointermove",function(t){var e=n.getBoundingClientRect(),a=(t.clientX-(e.left+e.width/2))/(e.width||1),d=(t.clientY-(e.top+e.height/2))/(e.height||1);r.forEach(function(u,p){var i=(p+1)*4*o;u.style.transform="translate("+(a*i).toFixed(1)+"px,"+(d*i).toFixed(1)+"px)"})}),n.addEventListener("pointerleave",function(){r.forEach(function(t){t.style.transform=""})})}}}})();
